%======================================================================
\section{Why mains electricity is AC}

\subsection{Everyday observation}
Every wall socket in Hong Kong delivers \textbf{alternating current} (a.c.):
the voltage between the live and neutral terminals reverses direction
\textbf{50 times every second}. Batteries and most phone chargers (after conversion)
use \textbf{direct current} (d.c.). Why did the power system choose a.c.?

\subsection{First-principles reasons for a.c.\ transmission}
\begin{enumerate}
  \item \textbf{Transformers need changing flux.}
        A transformer works by Faraday's law: a changing current in one coil
        induces emf in another. Steady d.c.\ produces no changing flux, so
        you cannot step voltage up or down with a simple transformer.
  \item \textbf{High voltage $\Rightarrow$ low current for the same power.}
        Power delivered is $P=VI$. For fixed $P$, raising $V$ lowers $I$.
        Cable heating loss is $I^{2}R$. Lower $I$ means far less wasted heat
        over long transmission lines.
  \item \textbf{Generation is naturally a.c.}
        Rotating generators (turbines + magnets/coils) produce an alternating emf
        by design. Converting everything to d.c.\ for transmission, then back again,
        is historically more expensive.
\end{enumerate}
So: generate a.c.\ $\to$ step up for transmission $\to$ step down near homes $\to$
deliver a safe-ish domestic voltage. The domestic chapter focuses on what arrives
at \emph{your} sockets and how wiring keeps people alive.

%======================================================================
\section{What ``220~V, 50~Hz'' means}

\subsection{The sinusoidal picture}
Mains voltage between live and neutral is (ideally) sinusoidal:
\[
V(t)=V_{0}\sin(2\pi f t),
\]
where $f=50\,\mathrm{Hz}$ in Hong Kong (and most of Europe/Asia).
One full cycle lasts
\[
T=\frac{1}{f}=\frac{1}{50}=0.020\,\mathrm{s}=20\,\mathrm{ms}.
\]

\begin{center}
\begin{tikzpicture}[x=0.55cm,y=0.55cm]
  \draw[-{Latex}] (0,0) -- (12.2,0) node[right,font=\small] {$t$};
  \draw[-{Latex}] (0,-2.8) -- (0,3.2) node[above,font=\small] {$V$};
  \draw[thick,blue!60!black,domain=0:11.5,samples=200]
    plot (\x,{2.4*sin(deg(2*pi*\x/5.5))});
  \draw[dashed] (0,2.4) -- (11.5,2.4) node[right,font=\scriptsize] {$+V_{0}$};
  \draw[dashed] (0,-2.4) -- (11.5,-2.4) node[right,font=\scriptsize] {$-V_{0}$};
  \draw[dashed,orange!70!black] (0,{2.4/1.414}) -- (11.5,{2.4/1.414})
    node[right,font=\scriptsize] {$V_{\mathrm{rms}}$};
  \node[font=\scriptsize] at (2.75,-3.3) {$T=20\,\mathrm{ms}$};
  \draw[{Latex}-{Latex}] (0,-3.05) -- (5.5,-3.05);
\end{tikzpicture}
\end{center}

\subsection{r.m.s.\ value --- the number on the socket}
Heating in a resistor depends on $I^{2}R$, so the useful measure of an a.c.\ voltage
is the \textbf{root-mean-square} (r.m.s.) value: the steady d.c.\ voltage that would
deliver the \emph{same average heating} in the same resistor.
For a pure sinusoid,
\[
V_{\mathrm{rms}}=\frac{V_{0}}{\sqrt{2}},\qquad
I_{\mathrm{rms}}=\frac{I_{0}}{\sqrt{2}},\qquad
P_{\mathrm{avg}}=V_{\mathrm{rms}}I_{\mathrm{rms}}
\quad\text{(resistive load)}.
\]
Hong Kong's ``220~V'' means
\[
V_{\mathrm{rms}}=220\,\mathrm{V}
\quad\Rightarrow\quad
V_{0}=V_{\mathrm{rms}}\sqrt{2}\approx 311\,\mathrm{V}.
\]
The peak-to-peak swing is $2V_{0}\approx 622\,\mathrm{V}$ --- much larger than 220~V.
\textbf{Never confuse peak, peak-to-peak, and r.m.s.}

\begin{mdframed}[style=misbox]
\noindent\textbf{Common slip.}
``Mains is 220~V so the voltage never exceeds 220~V.''
False: the instantaneous voltage reaches about $\pm 311\,\mathrm{V}$.
Meters and appliance ratings quote \textbf{r.m.s.}\ unless labelled otherwise.
\end{mdframed}

\begin{mdframed}[style=tipbox]
\noindent\textbf{DSE calculation pattern.}
Given $I_{\mathrm{rms}}$ and $R$: first $V_{\mathrm{rms}}=I_{\mathrm{rms}}R$, then
$V_{0}=V_{\mathrm{rms}}\sqrt{2}$. Frequency often appears only to distract.
\end{mdframed}

%======================================================================
\section{Energy, power, and the kilowatt-hour}

\subsection{From first principles}
Electric power is the rate of energy transfer:
\[
P=\frac{E}{t}=VI=I^{2}R=\frac{V^{2}}{R}.
\]
Energy transferred in time $t$ is $E=Pt$.
The SI unit of energy is the joule, but electricity bills use the
\textbf{kilowatt-hour}:
\[
1\,\mathrm{kW\,h}=(1000\,\mathrm{W})\times(3600\,\mathrm{s})=3.6\times 10^{6}\,\mathrm{J}.
\]
A kilowatt-hour meter measures \textbf{energy}, not power.
(Power would be read from a wattmeter or inferred as energy~/~time.)

\subsection{Worked calculation mindset}
\[
E\,(\mathrm{kW\,h})=P\,(\mathrm{kW})\times t\,(\mathrm{h}).
\]
Convert carefully: $1.5\,\mathrm{W}=0.0015\,\mathrm{kW}$, not $1.5\,\mathrm{kW}$.

\worked{2016}{28}{A}{77}{../2016_q28.png}{%
Energy in one month:
$E=P t=(1.5\times 10^{-3}\,\mathrm{kW})\times(16\times 30\,\mathrm{h})
=0.0015\times 480=0.72\,\mathrm{kW\,h}$.
CO$_2$ emission:
$0.72\times 0.8=0.576\,\mathrm{kg}$.
Trap options $576\,\mathrm{kg}$ and $720\,\mathrm{kg}$ forget the milli-prefix
or skip the $0.8$ factor. $\Rightarrow$ \textbf{A}.}

%======================================================================
\section{Live, neutral, and earth}

\subsection{Three different jobs}
A domestic cable typically carries three conductors:

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
Wire & Role & Ideal potential (wrt earth) \\
\midrule
\textbf{Live (L)} & Delivers alternating high potential from the supply &
  swings $\sim\pm 311\,\mathrm{V}$ (r.m.s.\ $220\,\mathrm{V}$) \\
\textbf{Neutral (N)} & Return path for operating current &
  near $0\,\mathrm{V}$ (earthed at the substation) \\
\textbf{Earth (E)} & Safety path only --- not used in normal operation &
  $0\,\mathrm{V}$ (connected to ground) \\
\bottomrule
\end{tabular}
\end{center}

\begin{itemize}
  \item In normal use, current flows \textbf{L $\to$ appliance $\to$ N}.
        The earth wire carries \textbf{no} current.
  \item Neutral is close to earth potential, but it is \emph{not} the earth wire:
        it is part of the working circuit.
  \item Because L is a.c., live is \textbf{sometimes positive and sometimes negative}
        with respect to neutral --- a frequent DSE true/false point.
\end{itemize}

\subsection{Hong Kong colour code}
\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
Wire & Modern (IEC) colours & Older colours (still in some buildings) \\
\midrule
Live & brown & red \\
Neutral & blue & black \\
Earth & green--yellow striped & green (or green--yellow) \\
\bottomrule
\end{tabular}
\end{center}

\begin{mdframed}[style=misbox]
\noindent\textbf{Common slip.}
``Earth is the return path for normal current.''
No --- that is neutral. Earth only becomes a current path under a
\textbf{fault} (live touching the metal case).
\end{mdframed}

\subsection{Three-pin plug (wiring face)}
