\section{QB\,404 examples}

\qbfig{PHY14041101--03 (p-01)}{B,\,D,\,D}{../../../_qb-assets/QB404/p-01.png}{%
\textbf{PHY14041101 (B).}
$V_{\mathrm{rms}}=I_{\mathrm{rms}}R=(5.3\times 10^{-3})(2\times 10^{3})=10.6\,\mathrm{V}$.
Peak: $V_{0}=10.6\sqrt{2}\approx 15\,\mathrm{V}$. Frequency is irrelevant.
\textbf{PHY14041102 (D).}
Same $\Delta\theta$ needs same energy $E$. With $R$ fixed,
$P\propto V^{2}$. Halving $V$ makes $P\to P/4$, so
$t=E/P\to 4\times 8=32\,\mathrm{min}$.
\textbf{PHY14041103 (D).}
$R=V_{\mathrm{r}}^{2}/P_{\mathrm{r}}=24^{2}/18=32\,\Omega$.
At $12\,\mathrm{V}$: $I_{1}=12/32=0.375\,\mathrm{A}$.
Max number: $5/0.375\approx 13.3\Rightarrow 13$ bulbs.}

\qbtext{PHY14041112}{%
Sharon bought a hairdryer from Japan rated at $110\,\mathrm{V}$.
In Japan the current is $I$ and power is $P$.
In Hong Kong she connects it to $220\,\mathrm{V}$.
Assume resistance unchanged. New current and power?
\begin{itemize}[leftmargin=1.8em]
  \item[A.] $\tfrac12 I$,\ $\tfrac14 P$
  \item[B.] $I$,\ $2P$
  \item[C.] $2I$,\ $P$
  \item[D.] $2I$,\ $4P$
\end{itemize}}{D}{%
$V\to 2V\Rightarrow I=V/R\to 2I$ and $P=V^{2}/R\to 4P$.
(Dangerous in real life --- the dryer would overheat --- but the MC asks the
ideal scaling.) $\Rightarrow$ \textbf{D}.}

\qbtext{PHY14041110}{%
Fuses available: $3\,\mathrm{A}$, $5\,\mathrm{A}$, $13\,\mathrm{A}$.
Appliances at $220\,\mathrm{V}$: lamp $48\,\mathrm{W}$, washing machine $360\,\mathrm{W}$,
hair dryer $1200\,\mathrm{W}$. Most suitable fuse combination?
\begin{itemize}[leftmargin=1.8em]
  \item[A.] $3$, $3$, $5$
  \item[B.] $3$, $3$, $13$
  \item[C.] $3$, $5$, $13$
  \item[D.] $5$, $5$, $13$
\end{itemize}}{B}{%
Currents: $I=P/V$ gives $0.22\,\mathrm{A}$, $1.64\,\mathrm{A}$, $5.45\,\mathrm{A}$.
Choose the next standard fuse above each operating current:
lamp $3\,\mathrm{A}$, washer $3\,\mathrm{A}$, dryer $13\,\mathrm{A}$
(not $5\,\mathrm{A}$, which is below $5.45\,\mathrm{A}$).
$\Rightarrow$ \textbf{B}.}

\qbfig{PHY14041104--05 (p-02)}{A,\,A}{../../../_qb-assets/QB404/p-02.png}{%
\textbf{PHY14041104 (A).}
Energy $=QV$ with $Q=(10\,000\times 10^{-3}\,\mathrm{A\,h})=10\,\mathrm{A\,h}$,
$V=5\,\mathrm{V}$:
$E=50\,\mathrm{W\,h}=0.050\,\mathrm{kW\,h}$.
Cost $=0.050\times 1.1=\$0.055$.
\textbf{PHY14041105 (A).}
Faster warming $\Rightarrow$ higher power on H: (1) true.
Supply voltage is still mains; H/L changes internal resistance/elements, not the
wall voltage: (2) false.
Different power at same $V$ means different effective $R$ between L and N:
(3) false.
$\Rightarrow$ (1) only $\Rightarrow$ \textbf{A}.}

%======================================================================
\section{Formula and safety summary}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Idea & Formula / rule \\
\midrule
r.m.s.\ (sinusoid) & $V_{\mathrm{rms}}=V_{0}/\sqrt{2}$,\ $I_{\mathrm{rms}}=I_{0}/\sqrt{2}$ \\
Average power (resistive) & $P=V_{\mathrm{rms}}I_{\mathrm{rms}}=I_{\mathrm{rms}}^{2}R=V_{\mathrm{rms}}^{2}/R$ \\
Energy / bill unit & $E=Pt$,\quad $1\,\mathrm{kW\,h}=3.6\times 10^{6}\,\mathrm{J}$ \\
Operating current & $I=P/V$ (use r.m.s.\ mains values) \\
Off-rating power & $P=P_{\mathrm{r}}(V/V_{\mathrm{r}})^{2}$ if $R$ fixed \\
Switch \& fuse & always on \textbf{live} \\
Earth & low-$R$ fault path L $\to$ case $\to$ earth; blows fuse \\
Double insulation & Class~II; may have no earth connection \\
\bottomrule
\end{tabular}
\end{center}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Before the exam --- five checks.}
(1)~Is 220~V r.m.s.\ or peak?
(2)~Is the meter measuring energy (kW\,h) or power (W)?
(3)~Is the fault L--N, L--E, or N--E?
(4)~Does this device protect against overcurrent or against leakage/shock?
(5)~Did the applied voltage match the rated voltage before you used $P_{\mathrm{r}}$?
\end{mdframed}

